using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.Interfaces;
using System.Threading;
using System.Threading.Tasks;

namespace SoulPilates.API.Controllers;

/// <summary>
/// SPM-127 — public, one-click unsubscribe for retention check-in reminder emails.
/// Linked from the retention email itself; no auth so the recipient can opt out in
/// a single click.
/// </summary>
[ApiController]
[Route("api/retention")]
public class RetentionController : ControllerBase
{
    private readonly IRetentionReminderService _retention;

    public RetentionController(IRetentionReminderService retention)
    {
        _retention = retention;
    }

    /// <summary>
    /// GET api/retention/unsubscribe?token=...
    /// Flips the client behind the opaque token to opted-out of retention reminders.
    /// Idempotent. Always returns the same neutral confirmation page so the endpoint
    /// can't be used to probe whether a given token exists.
    /// </summary>
    [AllowAnonymous]
    [HttpGet("unsubscribe")]
    public async Task<IActionResult> Unsubscribe([FromQuery] string? token, CancellationToken ct)
    {
        if (!string.IsNullOrWhiteSpace(token))
            await _retention.UnsubscribeByTokenAsync(token, ct);

        const string html =
            "<!doctype html><html lang='en'><head><meta charset='utf-8'>" +
            "<meta name='viewport' content='width=device-width, initial-scale=1'>" +
            "<title>Unsubscribed — Soul Pilates</title></head>" +
            "<body style='font-family:system-ui,Segoe UI,Arial,sans-serif;background:#faf9f7;margin:0;padding:48px 16px;text-align:center;color:#2a2a2a;'>" +
            "<div style='max-width:440px;margin:0 auto;background:#fff;border-radius:16px;padding:36px 28px;box-shadow:0 2px 12px rgba(0,0,0,0.06);'>" +
            "<h1 style='font-size:20px;margin:0 0 12px;'>You're unsubscribed</h1>" +
            "<p style='font-size:14px;line-height:1.6;color:#555;margin:0;'>You won't receive any more check-in reminder emails from Soul Pilates. " +
            "You'll still get essential emails about your bookings and payments. See you on the reformer!</p>" +
            "</div></body></html>";
        return Content(html, "text/html");
    }
}

