using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using SoulPilates.Core.Entities;
using System;
using System.Collections.Generic;

namespace SoulPilates.Core.Entities;

public class Client : BaseEntity
{
    public string FullName { get; set; } = null!;
    public string? Email { get; set; }
    public bool IsStudioRentalProfile { get; set; } = false;

    [BsonRepresentation(BsonType.ObjectId)]
    public string? StudioRentalStaffId { get; set; }

    /// <summary>
    /// National portion of the phone number, with no country dial code (e.g.
    /// <c>"901234567"</c> for a Vietnamese mobile, <c>"4155552671"</c> for a
    /// US line). Country dial code is stored separately on
    /// <see cref="PhoneCountryCode"/> per P2-S13.
    ///
    /// <para>
    /// Existing rows imported before P2-S13 ran the split migration may still
    /// contain a concatenated value here; the <c>split-phones</c> migration
    /// command separates them in-place. Code that needs the full E.164-style
    /// string for display should call <see cref="FullPhoneNumber"/>.
    /// </para>
    /// </summary>
    public string? PhoneNumber { get; set; }

    /// <summary>
    /// Country dial code with leading <c>"+"</c>, e.g. <c>"+84"</c> for Vietnam,
    /// <c>"+1"</c> for US/Canada. Null when unknown / not yet split.
    /// </summary>
    public string? PhoneCountryCode { get; set; }

    /// <summary>
    /// Convenience getter that concatenates <see cref="PhoneCountryCode"/> + a
    /// space + <see cref="PhoneNumber"/> for display. Returns just the national
    /// part when the dial code is missing, and null when both are absent.
    /// Not stored in Mongo — Bson serialiser is told to ignore it.
    /// </summary>
    [BsonIgnore]
    public string? FullPhoneNumber
    {
        get
        {
            if (string.IsNullOrWhiteSpace(PhoneNumber)) return null;
            return string.IsNullOrWhiteSpace(PhoneCountryCode)
                ? PhoneNumber
                : $"{PhoneCountryCode} {PhoneNumber}";
        }
    }

    public string ContactPlatform { get; set; } = "NONE"; // "WHATSAPP", "ZALO", "INSTAGRAM", "FACEBOOK", "SMS", "EMAIL", "NONE"
    public string? CountryOfOrigin { get; set; } = "Vietnam";
    public string? InternalNotes { get; set; }

    // New fields from frontend audit
    public string? MedicalHistory { get; set; }
    public List<string> Tags { get; set; } = new();
    public DateTime? DateOfBirth { get; set; }

    /// <summary>
    /// Self-reported acquisition channel captured at customer onboarding
    /// ("How did you hear about us?" — Instagram / Friend / Google / Walk-in /
    /// Other). Distinct from <see cref="ReferredByPartnerId"/> (a formal
    /// partner referral) and from web-analytics referrer tracking.
    /// </summary>
    public string? ReferralSource { get; set; }

    [BsonRepresentation(BsonType.ObjectId)]
    public string? ReferredByPartnerId { get; set; }

    public DateTime? FirstVisitDate { get; set; }
    // Seeded from the historical import, then kept live: incremented on every
    // recorded payment and decremented on refunds/voids (see InvoiceService).
    // VIP / Super VIP tiers are derived from this + attended classes against the
    // admin-configured thresholds (see GlobalSettings / ClientController).
    public decimal LifetimeValue { get; set; }

    /// <summary>Year the birthday email was last sent — so the daily job sends it at most once per year.</summary>
    public int? LastBirthdayEmailSentYear { get; set; }

    /// <summary>
    /// SPM — per-client win-back throttle. UTC timestamp of the last retention
    /// "win-back" email we sent this client. Non-null means the client has already
    /// been emailed for the CURRENT lapse and is suppressed across ALL their active
    /// packages/windows in <see cref="SoulPilates.Services.RetentionReminderService"/>,
    /// replacing the old per-package x per-window de-dupe that over-sent. Reset to
    /// null on a GENUINE new booking (WALK_IN/ONLINE create paths in
    /// SchedulingService/PaymentService) so a future lapse can be nudged again.
    /// Additive + nullable — deployable without a data migration; see the pre-prod
    /// backfill note in RetentionReminderService before enabling on production.
    /// </summary>
    public DateTime? WinBackEmailSentAt { get; set; }

    /// <summary>Highest VIP tier we've already emailed this client about ("VIP" / "SUPER_VIP").
    /// Null/empty = none sent yet. Prevents re-sending the achievement email each scan.</summary>
    public string? VipTierNotified { get; set; }

    // ── SPM-127 — retention-email opt-out ──
    /// <summary>
    /// SPM-127 — when true, the client has unsubscribed from retention check-in
    /// reminder emails (via the one-click link). Transactional emails (booking,
    /// payment, password reset, etc.) are unaffected.
    /// </summary>
    public bool RetentionRemindersOptedOut { get; set; } = false;

    /// <summary>
    /// SPM-127 — unguessable per-client token embedded in the retention email's
    /// one-click unsubscribe link. Generated lazily on first send; null until then.
    /// </summary>
    public string? UnsubscribeToken { get; set; }
}

