using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using System.Linq;
using System.Threading.Tasks;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/[controller]")]
// Module-gated: Admin/Receptionist reach it via their role defaults; specific
// instructors can be granted the "clients" module per-user (User.AllowedAdminModules).
[Authorize(Policy = "Module:clients")]
public class ClientController : ControllerBase
{
    private readonly IClientService _clientService;
    private readonly ISettingsService _settingsService;
    private readonly ICustomerAuthService _customerAuth;

    public ClientController(IClientService clientService, ISettingsService settingsService, ICustomerAuthService customerAuth)
    {
        _clientService = clientService;
        _settingsService = settingsService;
        _customerAuth = customerAuth;
    }

    /// <summary>Derive a client's VIP tier from the admin-configured thresholds.</summary>
    private static string ComputeVipTier(GlobalSettings s, decimal lifetime, int attended)
    {
        if (!s.EnableVipProgram) return "";
        if (lifetime >= s.SuperVipMinimumSpend && attended >= s.SuperVipMinimumClasses) return "SUPER_VIP";
        if (lifetime >= s.VipMinimumSpend) return "VIP";
        return "";
    }

    [HttpGet]
    public async Task<IActionResult> GetAll([FromQuery] string? search, [FromQuery] string? sort)
    {
        var clients = await _clientService.SearchClientsAsync(search ?? "");
        var settings = await _settingsService.GetAsync();
        var counts = await _clientService.GetCheckedInCountsAsync();
        var credits = await _clientService.GetActiveCreditsByClientAsync();
        // Only compute per-client recency when the caller asks to rank by it
        // (the top-bar quick search), so the default list path stays unchanged.
        var lastVisit = string.Equals(sort, "recent", StringComparison.OrdinalIgnoreCase)
            ? await _clientService.GetLastVisitByClientAsync()
            : null;
        var dtos = clients.Select(c =>
        {
            var attended = counts.GetValueOrDefault(c.Id ?? "", 0);
            var cr = credits.GetValueOrDefault(c.Id ?? "", (0, 0, 0));
            return new ClientDto
            {
                id = c.Id,
                name = c.FullName,
                email = c.Email,
                phone = c.PhoneNumber,
                phoneCountryCode = c.PhoneCountryCode,
                preferredContactPlatform = c.ContactPlatform,
                country = c.CountryOfOrigin,
                notes = c.InternalNotes,
                medicalHistory = c.MedicalHistory,
                tags = c.Tags,
                partnerCode = c.ReferredByPartnerId,
                dateOfBirth = c.DateOfBirth,
                createdAt = c.CreatedAt,
                firstVisitDate = c.FirstVisitDate,
                lifetimeValue = c.LifetimeValue,
                attendedClasses = attended,
                vipTier = ComputeVipTier(settings, c.LifetimeValue, attended),
                groupCredits = cr.Item1,
                matCredits = cr.Item2,
                privateCredits = cr.Item3,
            };
        });

        if (lastVisit is not null)
        {
            // Rank recently-active clients first, then by total visits, then name.
            dtos = dtos
                .OrderByDescending(d => lastVisit.TryGetValue(d.id ?? "", out var lv) ? lv : DateTime.MinValue)
                .ThenByDescending(d => d.attendedClasses)
                .ThenBy(d => d.name);
        }
        return Ok(dtos);
    }

    [HttpGet("{id}")]
    public async Task<IActionResult> GetById(string id)
    {
        var c = await _clientService.GetClientByIdAsync(id);
        if (c == null) return NotFound();
        var settings = await _settingsService.GetAsync();
        var attended = await _clientService.GetCheckedInCountAsync(id);
        var dto = new ClientDto
        {
            id = c.Id,
            name = c.FullName,
            email = c.Email,
            phone = c.PhoneNumber,
            phoneCountryCode = c.PhoneCountryCode,
            preferredContactPlatform = c.ContactPlatform,
            country = c.CountryOfOrigin,
            notes = c.InternalNotes,
            medicalHistory = c.MedicalHistory,
            referralSource = c.ReferralSource,
            tags = c.Tags,
            partnerCode = c.ReferredByPartnerId,
            dateOfBirth = c.DateOfBirth,
            createdAt = c.CreatedAt,
            firstVisitDate = c.FirstVisitDate,
            lifetimeValue = c.LifetimeValue,
            attendedClasses = attended,
            vipTier = ComputeVipTier(settings, c.LifetimeValue, attended),
        };
        // Portal account status drives the "send account setup email" button on the profile.
        var acct = await _customerAuth.GetAccountByClientIdAsync(id);
        dto.accountStatus = acct == null ? "none" : (acct.EmailVerified ? "active" : "pending");
        return Ok(dto);
    }

    /// <summary>
    /// Send (or re-send) an account-setup email to a guest client. Pre-creates a
    /// portal account from the client's name/email (phone stays on the client) and
    /// emails an activation link. Refused if the client already has an active
    /// account, or has no email on file.
    /// </summary>
    [HttpPost("{id}/account-invite")]
    [Authorize(Roles = "Admin,Receptionist,HeadInstructor,Manager")]
    public async Task<IActionResult> SendAccountInvite(string id)
    {
        var c = await _clientService.GetClientByIdAsync(id);
        if (c == null) return NotFound();
        if (string.IsNullOrWhiteSpace(c.Email))
            return BadRequest(new { error = "This client has no email on file — add one before sending an invite." });

        var acct = await _customerAuth.GetAccountByClientIdAsync(id);
        if (acct is { EmailVerified: true })
            return Conflict(new { error = "This client already has an active account." });

        // resend:true so a pending (invited-but-not-activated) account gets a fresh link.
        var result = await _customerAuth.SendActivationInvitesAsync(id, null, resend: true);
        if (result.NoEmail > 0)
            return BadRequest(new { error = "This client has no email on file." });
        if (result.Created == 0 && result.Resent == 0)
            return Conflict(new { error = "Nothing sent — the account may already be active." });

        return Ok(new { sent = true, email = c.Email, created = result.Created, resent = result.Resent });
    }

    /// <summary>
    /// All VIP + Super VIP clients (Super VIP first, then by spend). Backs the
    /// "VIP" tab on the clients page. Empty when the VIP program is disabled.
    /// </summary>
    [HttpGet("vips")]
    public async Task<IActionResult> GetVips()
    {
        var settings = await _settingsService.GetAsync();
        if (!settings.EnableVipProgram) return Ok(System.Array.Empty<ClientDto>());

        var clients = await _clientService.SearchClientsAsync("");
        var counts = await _clientService.GetCheckedInCountsAsync();
        var vips = clients
            .Select(c =>
            {
                var attended = counts.GetValueOrDefault(c.Id ?? "", 0);
                return (client: c, attended, tier: ComputeVipTier(settings, c.LifetimeValue, attended));
            })
            .Where(x => x.tier != "")
            .OrderByDescending(x => x.tier == "SUPER_VIP")
            .ThenByDescending(x => x.client.LifetimeValue)
            .Select(x => new ClientDto
            {
                id = x.client.Id,
                name = x.client.FullName,
                email = x.client.Email,
                phone = x.client.PhoneNumber,
                phoneCountryCode = x.client.PhoneCountryCode,
                country = x.client.CountryOfOrigin,
                tags = x.client.Tags,
                firstVisitDate = x.client.FirstVisitDate,
                createdAt = x.client.CreatedAt,
                lifetimeValue = x.client.LifetimeValue,
                attendedClasses = x.attended,
                vipTier = x.tier,
            });
        return Ok(vips);
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] ClientDto dto)
    {
        var client = new Client
        {
            FullName = dto.name,
            Email = dto.email,
            PhoneNumber = dto.phone,
            PhoneCountryCode = dto.phoneCountryCode,
            ContactPlatform = dto.preferredContactPlatform ?? "NONE",
            CountryOfOrigin = dto.country ?? "Vietnam",
            InternalNotes = dto.notes,
            MedicalHistory = dto.medicalHistory,
            Tags = dto.tags ?? new(),
            DateOfBirth = dto.dateOfBirth,
            // Normalise empty / whitespace partner id to null — the Mongo
            // serializer treats this field as an ObjectId and an empty
            // string would otherwise throw a BsonSerializationException
            // at insert-time ("'' is not a valid 24 digit hex string").
            ReferredByPartnerId = NormalisePartnerId(dto.partnerCode),
            // Lifecycle metrics are read-only over the wire; the importer
            // and downstream aggregators are the only writers. We
            // deliberately do not honour these on inbound bodies so an
            // operator can't accidentally overwrite computed stats.
        };
        var created = await _clientService.CreateClientAsync(client);
        dto.id = created.Id;
        return Ok(dto);
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> Update(string id, [FromBody] ClientDto dto)
    {
        // Preserve server-managed lifecycle metrics across PUT — the
        // inbound DTO doesn't carry authoritative FirstVisitDate /
        // LifetimeValue and a naive overwrite would zero them.
        var existing = await _clientService.GetClientByIdAsync(id);
        if (existing == null) return NotFound();

        var client = new Client
        {
            Id = id,
            FullName = dto.name,
            Email = dto.email,
            PhoneNumber = dto.phone,
            PhoneCountryCode = dto.phoneCountryCode,
            ContactPlatform = dto.preferredContactPlatform ?? "NONE",
            CountryOfOrigin = dto.country ?? "Vietnam",
            InternalNotes = dto.notes,
            MedicalHistory = dto.medicalHistory,
            // Preserve the onboarding-captured referral source across edits —
            // the client-edit form doesn't expose it, so fall back to the
            // stored value rather than nulling it out. (An explicit non-empty
            // value on the DTO still wins, allowing a future form to edit it.)
            ReferralSource = string.IsNullOrWhiteSpace(dto.referralSource) ? existing.ReferralSource : dto.referralSource,
            Tags = dto.tags ?? new(),
            DateOfBirth = dto.dateOfBirth,
            // Mirrors Create() — see normalisation comment above.
            ReferredByPartnerId = NormalisePartnerId(dto.partnerCode),
            // Carry lifecycle metrics forward from the existing document
            // so client-managed edits don't clobber server-computed state.
            FirstVisitDate = existing.FirstVisitDate,
            LifetimeValue = existing.LifetimeValue,
            CreatedAt = existing.CreatedAt,
        };
        await _clientService.UpdateClientAsync(id, client);
        return Ok();
    }

    /// <summary>
    /// Coerces an inbound partner-id string into a value safe for the Mongo
    /// <c>ObjectId</c> serializer:
    /// <list type="bullet">
    ///   <item><c>null</c>, empty, or whitespace → <c>null</c> (unlinked).</item>
    ///   <item>Any non-blank value is passed through verbatim. If the caller
    ///   sends a non-ObjectId string the serializer will still reject it at
    ///   insert time — we don't try to repair garbage here, only the
    ///   universally-common "empty form field" case.</item>
    /// </list>
    /// </summary>
    private static string? NormalisePartnerId(string? raw)
        => string.IsNullOrWhiteSpace(raw) ? null : raw.Trim();
}

