[HttpPut("{id}/email-subscription")]
public async Task<IActionResult> SetEmailSubscription(string id, [FromBody] EmailSubscriptionUpdateDto body)
{
    if (body == null) return BadRequest(new { error = "Missing body." });
    var existing = await _clientService.GetClientByIdAsync(id);
    if (existing == null) return NotFound();
    await _clientService.SetEmailSubscribedAsync(id, body.subscribed);
    return Ok(new { id, emailSubscribed = body.subscribed });
}

