window.setEmailSubscribed = async function (el) {
  const subscribed = !!el.checked;
  el.disabled = true;
  try {
    const res = await fetch(`${API}/api/client/${clientId}/email-subscription`, {
      method: "PUT",
      headers: {
        Authorization: "Bearer " + token,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ subscribed }),
    });
    if (!res.ok) throw new Error(`Failed (${res.status})`);
    const lbl = el.closest(".sp-switch");
    if (lbl) lbl.title = subscribed ? "Subscribed — click to unsubscribe" : "Unsubscribed — click to re-subscribe";
    (window.showToast || (() => {}))(
      subscribed ? "Client re-subscribed to check-in emails." : "Client unsubscribed from check-in emails.",
      "success",
    );
  } catch (e) {
    el.checked = !subscribed; // revert
    (window.showToast || ((m) => alert(m)))(
      "Could not update email subscription — " + (e.message || "please try again."),
      "error",
    );
  } finally {
    el.disabled = false;
  }
};

