            };
        })
        .OrderByDescending(r => r.TotalClasses)
        .ToList();
}

/// <summary>
/// Attribute every package PURCHASED within <paramref name="range"/> to the
/// instructor who most recently converted the buyer: the client's last
/// attended (CHECKED_IN / ARRIVED) class at or before the purchase
/// (activation) date — "last-touch" attribution. Returns instructorId →
/// packages-sold count. A package bought by a client with no prior attended
/// class is left unattributed (counted for nobody). Small collections
/// (hundreds of packages, low thousands of attendances) so this runs
/// in-memory rather than as a server-side aggregation.
/// </summary>
private async Task<Dictionary<string, int>> ComputePackagesSoldByInstructorAsync(AnalyticsRangeQuery range)
{
    var packages = await _clientPackages
        .Find(Builders<ClientPackage>.Filter.And(
            Builders<ClientPackage>.Filter.Gte(p => p.ActivationDate, range.StartDate),
            Builders<ClientPackage>.Filter.Lt(p => p.ActivationDate, range.EndDate)))
        .Project(p => new { p.ClientId, p.ActivationDate })
        .ToListAsync();
    if (packages.Count == 0) return new Dictionary<string, int>();

    var clientIds = packages
        .Select(p => p.ClientId)
        .Where(c => !string.IsNullOrEmpty(c))
        .Distinct()
        .ToList();
    if (clientIds.Count == 0) return new Dictionary<string, int>();

    // Every attended class for those buyers (across all time, not just the
    // window — the converting class may predate the analytics range).
    var atts = await _attendances
        .Find(Builders<Attendance>.Filter.And(
            Builders<Attendance>.Filter.In(a => a.ClientId, clientIds),
            Builders<Attendance>.Filter.In(a => a.Status, AttendedStatuses)))
        .Project(a => new { a.ClientId, a.CalendarSessionId })
        .ToListAsync();
    if (atts.Count == 0) return new Dictionary<string, int>();

    var attSessionIds = atts
        .Select(a => a.CalendarSessionId)
        .Where(s => !string.IsNullOrEmpty(s))
        .Distinct()
        .ToList();
    var sess = await _sessions
        .Find(Builders<CalendarSession>.Filter.In(s => s.Id, attSessionIds))
        .Project(s => new { s.Id, s.StartTime, s.InstructorId })
        .ToListAsync();
    var sessById = sess
        .Where(s => s.Id != null)
        .ToDictionary(s => s.Id!, s => s);

    // Per client: (classStartTime, instructorId) for attended classes, sorted ascending.
    var attendedByClient = new Dictionary<string, List<(DateTime start, string instr)>>();
    foreach (var a in atts)
    {
        if (string.IsNullOrEmpty(a.CalendarSessionId) ||
            !sessById.TryGetValue(a.CalendarSessionId!, out var s) ||
            string.IsNullOrEmpty(s.InstructorId))
            continue;
        if (!attendedByClient.TryGetValue(a.ClientId, out var list))
        {
            list = new List<(DateTime, string)>();
            attendedByClient[a.ClientId] = list;
        }
        list.Add((s.StartTime, s.InstructorId!));
    }
    foreach (var kv in attendedByClient)
        kv.Value.Sort((x, y) => x.start.CompareTo(y.start));

    var result = new Dictionary<string, int>();
    foreach (var p in packages)
    {
        if (string.IsNullOrEmpty(p.ClientId) ||
            !attendedByClient.TryGetValue(p.ClientId, out var list))
            continue;
        // Last attended class at or before the purchase (activation) date.
        string? instr = null;
        foreach (var e in list)
        {
            if (e.start <= p.ActivationDate) instr = e.instr;
            else break;
        }
        if (instr == null) continue;
        result[instr] = result.GetValueOrDefault(instr, 0) + 1;
    }
    return result;
}

