import 'dotenv/config';
import { PrismaClient } from '@prisma/client';
const db = new PrismaClient();
const PUSHED = 'cmsepl3ii000jhlo5npo7x8jw'; // Pushed to Staging

const DEPLOY = [
  'PROD DEPLOY (run when ready):',
  '  cd /opt/soulpilates-staging && git checkout main && git merge --ff-only feature/email-subscribe-instructor-metric && git push origin main',
  '  cd /opt/soulpilates && scripts/deploy-prod.sh',
  '(deploy-prod.sh builds :latest and recreates backend+frontend with --env-file prod.env, then smoke-tests. PR: https://github.com/santino1233/soulpilatescrm/pull/new/feature/email-subscribe-instructor-metric )',
].join('\n');

const card1 = `Done — two parts.

(a) LIVE PROD DATA FIX (COMPLETED): client 6a54b26a1d3c92cadac61bf5 = Hoai Doan (tinkream@gmail.com) had RetentionRemindersOptedOut:true. I backed up the full document, then set RetentionRemindersOptedOut:false on soulpilates-prod-mongo (matched=1, modified=1). She receives check-in emails again. Reversible. The email-subscription flag is the entity field RetentionRemindersOptedOut (true = unsubscribed); the one-click link flips it via RetentionController.UnsubscribeByTokenAsync.

(b) FEATURE (on STAGING): "Email subscribed" toggle added to the /admin/client-profile Account Info card — default ON, unchecks when a client is unsubscribed, flips the subscription live. Backend: ClientDto.emailSubscribed (= !RetentionRemindersOptedOut); GetById returns it; new PUT /api/client/{id}/email-subscription does a targeted single-field update (ClientService.SetEmailSubscribedAsync) — never a full document replace.

Also fixed a PRE-EXISTING data-integrity bug found here: the client edit-form PUT rebuilt the Client from a subset of fields and UpdateClientAsync does a full ReplaceOne, so every profile save silently wiped RetentionRemindersOptedOut / UnsubscribeToken / win-back+birthday+VIP throttles back to defaults — i.e. RE-SUBSCRIBING any unsubscribed client whose profile was saved. The generic PUT now preserves all server-managed state.

Verified on staging: images built, backend restarted clean (no crash-loop), new route registered + auth-enforced (401). Committed on branch feature/email-subscribe-instructor-metric (pushed to origin). Recommend deploying soon so the field-wipe bug stops silently resubscribing unsubscribed clients.

${DEPLOY}`;

const card2 = `Done (on STAGING). New per-instructor conversion metric added to the Instructor Performance table on /admin/analytics:
- Pkgs Sold: packages purchased in the period attributed (last-touch) to the instructor of the buyer's most recent attended class before the purchase.
- Classes/Pkg: classes taught ÷ packages converted (lower = better at converting attendees into package buyers).

Backend: InstructorPerformanceDto.PackagesSold + ClassesPerPackage; AnalyticsService.ComputePackagesSoldByInstructorAsync (attended = CHECKED_IN/ARRIVED; purchase timestamp = ClientPackage.ActivationDate; classes-taught denominator = the existing completed non-freelance sessions-with-attendees rule). Frontend: two new columns (also fixed the Classes column, which was reading a stale 'classesHeld' field and rendering 0).

Validated read-only against staging data (synced from prod, Dec 2025 - Aug 2026): 123 packages in range, 50 attributed / 73 with no prior attended class (correctly left unattributed). Nakko: 601 classes, 47 pkgs, 12.79 classes/pkg (top converter). Linna: 61 classes, 3 pkgs, 20.33 classes/pkg. Numbers match the shipped C# logic exactly.

Committed on branch feature/email-subscribe-instructor-metric (pushed to origin). Same PROD DEPLOY as the other card.

${DEPLOY}`;

async function fin(id, body) {
  await db.cardComment.create({ data: { cardId: id, authorName: 'Claude', body } });
  await db.card.update({ where: { id }, data: { columnId: PUSHED, position: 0 } });
  console.log('finalized', id);
}
await fin('cmsft7sqc0002hln8s5m3lzga', card1);
await fin('cmsftkuaw0006hln8a3r7oohu', card2);
await db.$disconnect();
